const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const header=document.querySelector('header'),heroArt=document.querySelector('.hero-art'),templeArt=document.querySelector('.temple-art'),descent=document.querySelector('.descent'),progress=document.querySelector('.progress div');
let paused=reduced.matches,party=false,raf=0;
const motion=document.querySelector('#motion');
function setPaused(value){paused=value;document.body.classList.toggle('paused',value);motion.setAttribute('aria-pressed',String(value));motion.setAttribute('aria-label',value?'Reprendre les animations':'Mettre les animations en pause');motion.textContent=value?'▷':'Ⅱ';if(value){heroArt.style.transform='none';templeArt.style.transform='none';}updateScene();}
motion.addEventListener('click',()=>setPaused(!paused));reduced.addEventListener('change',()=>setPaused(reduced.matches));setPaused(paused);
const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=header.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');menu.textContent=open?'×':'☰';});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{header.classList.remove('menu-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu');menu.textContent='☰';}));
function updateScene(){const y=scrollY,h=innerHeight;header.classList.toggle('scrolled',y>h*.65);progress.style.transform=`scaleX(${Math.min(1,y/Math.max(1,document.documentElement.scrollHeight-h))})`;if(!paused&&!reduced.matches){if(y<h)heroArt.style.transform=`translate3d(0,${y*.23}px,0) scale(1.025)`;const top=descent.offsetTop;if(y>top-h&&y<top+descent.offsetHeight){const offset=Math.max(-30,Math.min(30,(y-top)/h*18));templeArt.style.transform=`translate3d(0,${-offset}px,0) scale(1.045)`;}}raf=0;}
window.addEventListener('scroll',()=>{if(!raf)raf=requestAnimationFrame(updateScene);},{passive:true});window.addEventListener('resize',updateScene);updateScene();
const eventDate=new Date('2027-01-30T00:00:00+01:00');function countdown(){let diff=Math.max(0,eventDate-Date.now());document.querySelector('#days').textContent=Math.floor(diff/86400000);document.querySelector('#hours').textContent=String(Math.floor(diff/3600000)%24).padStart(2,'0');document.querySelector('#minutes').textContent=String(Math.floor(diff/60000)%60).padStart(2,'0');if(diff===0){document.querySelector('.countdown').setAttribute('aria-label','Le rendez-vous est arrivé');}}countdown();setInterval(countdown,30000);
const ideas=['Pharaon disco : couronne dorée, lunettes et paillettes.','Cléopâtre de minuit : bleu profond, or et regard de reine.','Momie chic : bandelettes, touche fluo et baskets confortables.','Gardien du temple : col large, motifs géométriques et allure royale.','Scarabée cosmique : reflets métallisés et ailes imaginaires.','Explorateur du Nil : chapeau, carte au trésor et curiosité.'];let idea=0;document.querySelector('#inspire').addEventListener('click',()=>{document.querySelector('#costume-idea').textContent=ideas[idea++%ideas.length];});
const canvas=document.querySelector('#confetti'),ctx=canvas.getContext('2d');let w,h,particles=[];function resize(){w=canvas.width=canvas.clientWidth;h=canvas.height=canvas.clientHeight;particles=Array.from({length:75},()=>({x:Math.random()*w,y:Math.random()*h,r:Math.random()*3+2,v:Math.random()*1.3+.5,phase:Math.random()*6.28,color:['#ffd58c','#7ce8e3','#e6a1ed','#ffb391'][Math.floor(Math.random()*4)]}));}resize();window.addEventListener('resize',resize);const partyButton=document.querySelector('#party');partyButton.addEventListener('click',()=>{party=!party;document.body.classList.toggle('party',party);partyButton.setAttribute('aria-pressed',String(party));partyButton.innerHTML=party?'<span aria-hidden="true">✧</span> Le temple s’éveille !':'<span aria-hidden="true">✧</span> Réveiller le temple';if(party&&reduced.matches){document.querySelector('.hero-tagline').textContent='Le temple est prêt. Il ne manque plus que vous.';}});let last=0;function confetti(now){if(now-last>30){last=now;ctx.clearRect(0,0,w,h);if(party&&!paused&&!reduced.matches&&scrollY<h){particles.forEach(p=>{p.y+=p.v;p.x+=Math.sin(p.y*.007+p.phase)*.4;if(p.y>h){p.y=-10;p.x=Math.random()*w;}ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.y*.01+p.phase);ctx.fillStyle=p.color;ctx.fillRect(-p.r/2,-p.r,p.r,p.r*2);ctx.restore();});}}requestAnimationFrame(confetti);}requestAnimationFrame(confetti);
